static usize pack_mqtt_header(const union mqtt_header *hdr, u8 *buf)
{
    pack(buf++, "B", hdr->byte);

    /* Encode 0 length bytes, message like this have only a fixed header */
    mqtt_encode_length(buf, 0);

    return MQTT_HEADER_LEN;
}
